-- Generated by scripts/content/sat-pb-modules.mjs --practice-additions.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
insert into public.sat_playbook_page_sections(id,page_id,block_type,heading,status,sort_order,content,metadata)
select v.id,p.id,'rich_text','Worked Example and Try It','published',
  coalesce((select max(s.sort_order) from public.sat_playbook_page_sections s where s.page_id=p.id),0)+1,
  v.content,'{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-practice-2026-11-v1"}'::jsonb
from (values
  (md5('schood-sat-pb-page:desmos-and-calculator-strategy')::uuid, md5('schood-sat-pb-section:desmos-and-calculator-strategy:eight-week-practice')::uuid, '{"markdown":"**Worked example.** Consider x² − 13x + 40 = 0 with the restriction x > 6. A graph of `y=x^2-13x+40` crosses the x-axis at 5 and 8. Apply the written restriction after using the graph: the only allowed root is 8. Substitution gives 64 − 104 + 40 = 0.\n\n**Try it.** Graph `y=(x-2)(x-7)`. A task asks for the zero that is at least 6, then asks for twice that zero. What do you enter?\n\n**Check your work.** The roots are 2 and 7. The restriction leaves 7 and twice 7 is 14. The calculator supplies the roots, while the prompt determines the final entry."}'::jsonb),
  (md5('schood-sat-pb-page:math-advanced-math')::uuid, md5('schood-sat-pb-section:math-advanced-math:eight-week-practice')::uuid, '{"markdown":"**Worked example.** Find the nonnegative x for which (x² + 1)² = 25. Taking square roots gives x² + 1 = 5 or x² + 1 = −5. The expression x² + 1 is positive for all real x, so only the first equation is possible. It gives x² = 4 and x = 2 in the stated domain.\n\n**Try it.** How many real numbers x satisfy (x² − 6)² = 4?\n\n**Check your work.** Here both branches can occur: x² − 6 = 2 or x² − 6 = −2. These yield x² = 8 or x² = 4, each with two real roots. The answer is four."}'::jsonb),
  (md5('schood-sat-pb-page:math-algebra')::uuid, md5('schood-sat-pb-section:math-algebra:eight-week-practice')::uuid, '{"markdown":"**Worked example.** A printing service charges 14 dollars per file and subtracts one 8-dollar credit from the bill. The bill for a group of files is 62 dollars. For f files, 14f − 8 = 62, so 14f = 70 and f = 5. Substitution checks the result: 70 − 8 = 62.\n\n**Try it.** A second service charges 11 dollars per file and adds a one-time 7-dollar setup charge. For how many files would both services give the same bill, assuming the first service still applies its credit?\n\n**Check your work.** Set 14f − 8 = 11f + 7. Then 3f = 15, so f = 5. Both bills are 62 dollars. Keep one-time adjustments outside the per-file multiplication."}'::jsonb),
  (md5('schood-sat-pb-page:math-geometry-trigonometry')::uuid, md5('schood-sat-pb-section:math-geometry-trigonometry:eight-week-practice')::uuid, '{"markdown":"**Worked example.** A circular sign insert has radius 9 centimeters and a central angle of 80°. Its curved edge is 80/360 = 2/9 of the circumference, so its arc is (2/9)(18π) = 4π centimeters. The full border also includes two radius edges and is 18 + 4π centimeters.\n\n**Try it.** A circular-sector panel has radius 12 centimeters and a 45° central angle. How much longer is its complete border than its curved edge?\n\n**Check your work.** The two straight edges are each a radius. The full border is 24 centimeters longer. No arc calculation is needed for this difference."}'::jsonb),
  (md5('schood-sat-pb-page:math-problem-solving-data-analysis')::uuid, md5('schood-sat-pb-section:math-problem-solving-data-analysis:eight-week-practice')::uuid, '{"markdown":"**Worked example.** At a library workshop, 12 of 20 first-time visitors finish a task, and 18 of 60 returning visitors finish it. To find the overall rate, combine the actual counts: (12 + 18)/(20 + 60) = 30/80 = 37.5%. Averaging 60% and 30% gives 45%, which weights the smaller group too heavily.\n\n**Try it.** A similar event has 15 successes out of 25 in its first group and 15 successes out of 75 in its second. What percentage of all attendees succeed?\n\n**Check your work.** There are 30 successes among 100 attendees, so the overall rate is 30%. Equal numbers of successes can come from groups with unequal rates."}'::jsonb),
  (md5('schood-sat-pb-page:pacing-and-adaptive-modules')::uuid, md5('schood-sat-pb-section:pacing-and-adaptive-modules:eight-week-practice')::uuid, '{"markdown":"**Worked example.** With 4 minutes left, Tessa sees two unanswered questions and one flagged question with an answer already entered. She estimates that one unanswered item will take 35 seconds and the other could take 2 minutes. She takes the quick item first, then starts the longer one. She leaves time to enter a final answer and returns to the flagged choice if time remains.\n\n**Try it.** You have 2 minutes left. One problem is still blank and your last attempt to set it up stalled. Another is flagged because you suspect a sign error and already have the equation written. What do you do first?\n\n**Check your work.** Enter a best guess for the blank problem, then check the known sign in the flagged one. Return to the harder setup if you have time. A blank is avoidable even when the full reasoning takes longer."}'::jsonb),
  (md5('schood-sat-pb-page:reading-writing-conventions')::uuid, md5('schood-sat-pb-section:reading-writing-conventions:eight-week-practice')::uuid, '{"markdown":"**Worked example.** “The files from the older recorder, along with a written list of their dates, **were** sent to the archive.” Cross out the removable phrase _along with a written list of their dates_. The subject is still the plural noun _files_, so _were_ is the correct verb.\n\n**Try it.** “The map of the shoreline, with two newer sketches attached, ___ on the inside cover.” Choose _appears_ or _appear_.\n\n**Check your work.** Choose _appears_. The subject is _map_. _Shoreline_ belongs to the _of_ phrase, and _sketches_ belongs to the inserted _with_ phrase."}'::jsonb),
  (md5('schood-sat-pb-page:reading-writing-craft-structure')::uuid, md5('schood-sat-pb-section:reading-writing-craft-structure:eight-week-practice')::uuid, '{"markdown":"**Worked example.** One composer attributes the popularity of a short concert series to its early evening start. A venue manager accepts that attendance grew but notes that the venue added a bus stop before the same season. The manager would question the proposed explanation. Both accounts accept the attendance result.\n\n**Try it.** Text 1 argues that an orchard guide''s handwritten notes show readers used it on outdoor walks. Text 2 agrees that the notes record practical observations but points out that entries were copied from a separate survey. What claim from Text 1 would the author of Text 2 most likely challenge?\n\n**Check your work.** Challenge the inference about where readers used the guide. The notes'' practical content is common ground. [Practice comparing paired passages](https://practice.sat.schood.online/short-sets?set=paired-01)."}'::jsonb),
  (md5('schood-sat-pb-page:reading-writing-expression-of-ideas')::uuid, md5('schood-sat-pb-section:reading-writing-expression-of-ideas:eight-week-practice')::uuid, '{"markdown":"**Worked example.** A student has notes about two ferry routes. Both take 22 minutes; one has three docking points and the other has one. The writing goal is to emphasize shared travel time. “Both ferry routes take 22 minutes” addresses that goal directly. Bringing in docking points would shift attention to the difference.\n\n**Try it.** A volunteer group spent 6 hours cataloging photographs in April and 9 hours in May. It identified the years of 32 photographs in April and 36 in May. Write one sentence emphasizing the change in hours.\n\n**Check your work.** “The group spent three more hours cataloging photographs in May than in April.” The number of dated photographs answers a separate question about output."}'::jsonb),
  (md5('schood-sat-pb-page:reading-writing-information-ideas')::uuid, md5('schood-sat-pb-section:reading-writing-information-ideas:eight-week-practice')::uuid, '{"markdown":"**Worked example.** An archive tests two labels for audio clips. With Label A, 18 of 30 listeners identify the clip''s source. With Label B, 25 of 50 do. A researcher says the higher share identifies the source with Label A. Compare 18/30 = 60% and 25/50 = 50%. The larger number of successful listeners comes from Label B, but the claim compares shares.\n\n**Try it.** In a second test, 28 of 40 listeners succeed with Label A and 33 of 60 succeed with Label B. Which single sentence reports the evidence for the claim accurately?\n\n**Check your work.** “A higher percentage succeeded with Label A (70%) than with Label B (55%).” Calling the difference 5 points would compare counts in place of percentages. [Practice with evidence charts](https://practice.sat.schood.online/short-sets?set=evidence-01)."}'::jsonb),
  (md5('schood-sat-pb-page:retake-and-superscore-strategy')::uuid, md5('schood-sat-pb-section:retake-and-superscore-strategy:eight-week-practice')::uuid, '{"markdown":"**Worked example.** A student earns 680 in Reading and Writing and 720 in Math on one sitting, then 710 in Reading and Writing and 700 in Math on another. An institution that accepts superscores could use 710 + 720 = 1430. The two single-sitting totals are 1400 and 1410.\n\n**Try it.** A student earns 730 and 650 on the first sitting, then 710 and 690 on the second. What are the best single-sitting total and the superscore, assuming the institution accepts it?\n\n**Check your work.** The single-sitting totals are 1380 and 1400, so the best is 1400. The highest section scores are 730 and 690, which add to 1420. The institution''s current policy determines which calculation applies."}'::jsonb),
  (md5('schood-sat-pb-page:sat-essentials')::uuid, md5('schood-sat-pb-section:sat-essentials:eight-week-practice')::uuid, '{"markdown":"**Worked example.** Nora has 25 minutes on a school day. Her last practice log shows three mistakes on boundary questions and one guessed Math question she got right. She spends 12 minutes on a boundary drill, 8 minutes solving the guessed Math problem without options, and 5 minutes recording the rules she used. The two parts of the log call for different work: repair a recurring error and verify a lucky answer.\n\n**Try it.** Eli has 20 minutes. On his last drill, he got two easy slope questions wrong and solved a difficult geometry question correctly after slow work. Which should he practice first, and what should he save from the geometry question?\n\n**Check your work.** Start with slope because the same gap cost two accessible points. Save the geometry setup or a shorter method to rehearse during a timed session."}'::jsonb),
  (md5('schood-sat-pb-page:score-goals-and-study-plans')::uuid, md5('schood-sat-pb-section:score-goals-and-study-plans:eight-week-practice')::uuid, '{"markdown":"**Worked example.** Rae sees three recent errors on quantitative evidence and two on transition questions. She has 45 minutes this week. She schedules an 18-minute evidence drill, a 12-minute transition drill, and a 15-minute mixed check on another day. At the check she records one comparison rule and one transition relationship she can apply again.\n\n**Try it.** You have 40 minutes. Your last two drills showed three misses on two-variable equations, one on circles, and several unfinished questions. Assign two practice blocks and a brief outcome check.\n\n**Check your work.** One workable split is 18 minutes on two-variable equations, 12 minutes on a timed mixed drill, and 10 minutes reviewing missed or unfinished questions. One circle miss is worth logging, but the repeated equation and timing issues guide this week''s allocation."}'::jsonb),
  (md5('schood-sat-pb-page:test-day-guide')::uuid, md5('schood-sat-pb-section:test-day-guide:eight-week-practice')::uuid, '{"markdown":"**Worked example.** A student has rehearsed with one device and an external mouse. During a practice module, the mouse stops working. The student continues with the trackpad and discovers that dragging the on-screen calculator feels different. Before the next rehearsal, the student repeats three familiar problems with the trackpad to build a fallback routine.\n\n**Try it.** Pick one tool you tend to rely on. During an untimed practice question, rehearse continuing without that tool. What part takes longer, and what can you prepare before test day?\n\n**Check your work.** Record a specific fallback, such as typing an equation into the calculator instead of dragging a graph, or flagging a question and returning to it. Practice that action once during your next timed module."}'::jsonb)
) as v(page_id,id,content)
join public.sat_playbook_pages p on p.id=v.page_id and p.product_id='a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'
on conflict (id) do nothing;
commit;
